"""Layout-only guards must not throw away a fact-checked model micro-post (2026-10-21).

Cloud evidence (run 39577216468, 17:29 Beijing, ``publish_standalone`` top-up):

* 3 candidates were generated by the model with 524 / 338 / 553 chars;
* each was rejected with ``story_opening_length_guard`` — the *first paragraph*
  was longer than the 90-character feed opening limit;
* the caller then switched to ``build_local_fallback_content``, which
  intentionally returns "" for story context (no padding), so the batch ended
  with ``content_too_short`` and published 0 posts (``today_count_before`` ==
  ``today_count_after`` == 1, target 2).

The guard is about *layout*, and the repository already has a deterministic
reflow (``_reflow_verified_feed``) that keeps every sentence but re-paragraphs
them so the opening is exactly two sentences. It was only applied after the
fact-review step, never before the fallback decision. These tests pin the
recovery so a layout-only complaint reflows the model draft instead of
destroying it.
"""

from __future__ import annotations

import json
import logging
from pathlib import Path
from unittest.mock import MagicMock

from toutiao_content_factory.models import TopicCandidate
from toutiao_content_factory.services.weitoutiao_generator import (
    WeiToutiaoStandaloneGenerator,
)

LEAD = (
    "小区业主因为拒交停车费与物业公司发生争执并最终把对方告上了法庭。"
    "法院审理查明物业公司多年来一直没有公示停车费的收支明细和公共收益。"
    "判决书要求物业公司在十日内公开最近三年的收费账本并说明资金去向。"
    "双方随后就此前欠缴的停车费金额如何补交继续协商尚未达成一致意见。"
)
BODY_1 = (
    "从这件事可以看出，收费是否合理，第一步看账目是否公开，"
    "第二步看业主大会有没有授权，第三步看欠费金额有没有逐笔核对。"
)
BODY_2 = (
    "对业主来说，遇到类似争议，先保存缴费记录和物业服务合同，"
    "再按程序要求公开账目，避免把争议变成情绪对立。"
)
LONG_OPENING_DRAFT = f"{LEAD}\n\n{BODY_1}\n\n{BODY_2}\n\n#社会热点 #生活观察"


def _story_topic() -> TopicCandidate:
    topic = TopicCandidate(
        title="业主拒交停车费把物业告上法庭",
        url="https://example.test/parking",
        source="公开信息",
        source_type="test",
        summary="业主要求物业公开停车费收支账本，法院判决物业限期公开收费明细。",
        snippet="业主与物业因停车费收支公开问题产生纠纷，法院判决期限公开。",
        matched_keywords=["物业", "停车费", "业主"],
        rank=1,
        total_score=88,
    )
    topic._content_experiment = {
        "id": "story_opening_v1",
        "variant": "result_first",
        "protocol_version": 4,
        "selection_protocol": "settled_revenue_v1",
        "category": "consumer_practical",
        "trial_id": "robot_notes_profit_20261018",
        "body_structure": "facts_distinction_boundary_v1",
    }
    return topic


def _generator(app_settings) -> WeiToutiaoStandaloneGenerator:
    return WeiToutiaoStandaloneGenerator(app_settings, logging.getLogger("test.wtt.layout"))


def _chars(text: str) -> int:
    return len("".join(text.split()))


def test_layout_only_guard_is_repaired_by_reflow(app_settings) -> None:
    generator = _generator(app_settings)
    topic = _story_topic()

    assert generator._model_story_fallback_reason(topic, "story_comment", LONG_OPENING_DRAFT) == (
        "story_opening_length_guard"
    )

    recovered = generator._recover_layout_only_guard(topic, "story_comment", LONG_OPENING_DRAFT)

    assert recovered, "a layout-only rejection must be reflowed, not discarded"
    assert generator._model_story_fallback_reason(topic, "story_comment", recovered) == ""
    # Reflow may only change layout, never drop or add prose.
    assert _chars(recovered) == _chars(LONG_OPENING_DRAFT)
    opening = recovered.split("\n\n")[0]
    assert _chars(opening) <= 90
    assert opening.endswith("。")


def test_unfixable_opening_is_not_recovered(app_settings) -> None:
    generator = _generator(app_settings)
    topic = _story_topic()
    single_long_sentence = "这是一个长度超过九十个字符因而无法通过两句话开头规则的长句" * 4 + "。"

    assert generator._model_story_fallback_reason(
        topic, "story_comment", single_long_sentence
    ) == "story_opening_length_guard"
    assert generator._recover_layout_only_guard(
        topic, "story_comment", single_long_sentence
    ) == ""


def test_non_layout_guard_is_not_recovered(app_settings) -> None:
    generator = _generator(app_settings)
    topic = _story_topic()
    padded = (
        "最稳妥的做法是记录事实、标注推测，并随着新信息更新结论。"
        "这条消息值得看，但价值不只在热闹本身，更在它暴露出的后续观察方向。"
    )

    assert generator._model_story_fallback_reason(topic, "story_comment", padded) == (
        "story_reader_value_guard"
    )
    assert generator._recover_layout_only_guard(topic, "story_comment", padded) == ""


def test_batch_keeps_model_post_after_layout_reflow(app_settings) -> None:
    object.__setattr__(app_settings.publishing, "weitoutiao_enabled", True)
    # Production robot_notes runs with the story_comment persona; the feed
    # opening guard is a story-domain rule.
    object.__setattr__(app_settings.publishing, "weitoutiao_personas", ["story_comment"])
    generator = _generator(app_settings)
    generator._iter_eligible_topics = MagicMock(return_value=[_story_topic()])
    generator.generate_content = MagicMock(return_value=LONG_OPENING_DRAFT)
    generator.publish_service.publish_weitoutiao = MagicMock(
        return_value={
            "status": "submitted_for_review",
            "published_at": "2026-10-21T17:35:00",
            "external_url": "https://example.test/weitoutiao",
        }
    )

    result = generator.publish_standalone(count=1, purpose="test_layout_reflow")

    assert result["status"] == "success"
    assert result["accepted"] == 1
    assert result["fallback_used"] is False
    published = result["published"][0]
    assert published["generation_mode"] == "model"

    run_dir = Path(published["run_dir"])
    publish_meta = json.loads(
        (run_dir / app_settings.review.publish_dirname / "publish_meta.json").read_text(
            encoding="utf-8"
        )
    )
    assert publish_meta["content_char_count"] >= 200
    assert publish_meta["generation_mode"] == "model"
    article = (run_dir / app_settings.review.publish_dirname / "article.md").read_text(
        encoding="utf-8"
    )
    assert _chars(article.split("\n\n")[0]) <= 90
